// SplitPair splits a Kraken pair symbol into base and quote currencies.
// Returns normalized currency names (e.g. "BTC", "USD" not "XXBT", "ZUSD").
func SplitPair(pair string) (base, quote string, ok bool) {
	if info, found := Pairs[pair]; found {
		return info.Base, info.Quote, true
	}
	return "", "", false
}
